CREATE TABLE IF NOT EXISTS food_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES food_listings(id), requester_id uuid NOT NULL REFERENCES user_accounts(id), quantity integer NOT NULL CHECK(quantity > 0), status text NOT NULL DEFAULT 'pending', reason text NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL);
ALTER TABLE pickups ADD COLUMN IF NOT EXISTS request_id uuid NULL REFERENCES food_requests(id); ALTER TABLE pickups ADD COLUMN IF NOT EXISTS listing_id uuid NULL REFERENCES food_listings(id); ALTER TABLE pickups ADD COLUMN IF NOT EXISTS recipient_id uuid NULL REFERENCES user_accounts(id); ALTER TABLE pickups ADD COLUMN IF NOT EXISTS community_id uuid NULL REFERENCES communities(id); ALTER TABLE pickups ADD COLUMN IF NOT EXISTS verification_status text NOT NULL DEFAULT 'pending'; ALTER TABLE pickups ADD COLUMN IF NOT EXISTS dispute_status text NOT NULL DEFAULT 'none'; ALTER TABLE pickups ADD COLUMN IF NOT EXISTS completed_at timestamptz NULL;
CREATE INDEX IF NOT EXISTS idx_food_requests_status ON food_requests(status); CREATE INDEX IF NOT EXISTS idx_pickups_status ON pickups(status);
